  // \u5173\u95ED\u8FDE\u63A5\n  close() {\n    if (this.ws) {\n      this.ws.close();\n      this.ws = null;\n    }\n  }\n}\n\nexport default WebSocketClient;\n"})}),"\n",(0,r.jsxs)(n.p,{children:["\u8FD9\u4E2A\u57FA\u7840\u7248\u672C\u5C01\u88C5\u4E86WebSocket\u7684\u6838\u5FC3\u64CD\u4F5C\uFF0C\u4F7F\u7528\u4E86\u89C2\u5BDF\u8005\u6A21\u5F0F\uFF08Observer Pattern\uFF09\u6765\u7BA1\u7406\u4E8B\u4EF6\u76D1\u542C\u3002\u5916\u90E8\u4EE3\u7801\u901A\u8FC7",(0,r.jsx)(n.code,{children:"on('message', callback)"}),"\u6765\u76D1\u542C\u6D88\u606F\u4E8B\u4EF6\uFF0C\u901A\u8FC7",(0,r.jsx)(n.code,{children:"send()"}),"\u65B9\u6CD5\u6765\u53D1\u9001\u6D88\u606F\uFF0C\u4E0D\u9700\u8981\u76F4\u63A5\u64CD\u4F5CWebSocket\u5B9E\u4F8B\u3002\u8FD9\u79CD\u5C01\u88C5\u7684\u597D\u5904\u662F\u5982\u679C\u5C06\u6765\u9700\u8981\u66F4\u6362\u5E95\u5C42\u901A\u4FE1\u5E93\u6BD4\u5982\u6362\u6210Socket.IO\u6216\u8005\u539F\u751F\u6A21\u5757\uFF0C\u53EA\u9700\u8981\u4FEE\u6539\u8FD9\u4E2A\u7C7B\u7684\u5185\u90E8\u5B9E\u73B0\uFF0C\u5916\u90E8\u8C03\u7528\u4EE3\u7801\u5B8C\u5168\u4E0D\u9700\u8981\u6539\u52A8\uFF0C\u7B26\u5408\u4F9D\u8D56\u5012\u7F6E\u7684\u8BBE\u8BA1\u539F\u5219\u3002"]}),"\n",(0,r.jsx)(n.h3,{id:"763-\u6D88\u606F\u6536\u53D1\u4E0E\u6570\u636E\u89E3\u6790\u5904\u7406",children:"7.6.3 \u6D88\u606F\u6536\u53D1\u4E0E\u6570\u636E\u89E3\u6790\u5904\u7406"}),"\n",(0,r.jsx)(n.p,{children:"WebSocket\u6D88\u606F\u901A\u5E38\u662FJSON\u683C\u5F0F\u7684\u6587\u672C\uFF0C\u4F46\u4E5F\u53EF\u4EE5\u662F\u4E8C\u8FDB\u5236\u6570\u636E\u3002\u5728\u5B9E\u9645\u4E1A\u52A1\u4E2D\uFF0C\u6D88\u606F\u901A\u5E38\u6709\u4E00\u4E2A\u7EDF\u4E00\u7684\u534F\u8BAE\u683C\u5F0F\uFF0C\u5305\u542B\u6D88\u606F\u7C7B\u578B\u3001\u6570\u636E\u4F53\u7B49\u5B57\u6BB5\uFF1A"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-js",children:'// \u6D88\u606F\u534F\u8BAE\u683C\u5F0F\u5B9A\u4E49\n// {\n//   "type": "chat",        // \u6D88\u606F\u7C7B\u578B\n//   "from": "user_123",    // \u53D1\u9001\u8005\n//   "to": "user_456",      // \u63A5\u6536\u8005\n//   "data": {              // \u6D88\u606F\u6570\u636E\n//     "text": "\u4F60\u597D",\n//     "timestamp": 1690000000000\n//   }\n// }\n\n// \u6D88\u606F\u5904\u7406\u5668\nconst messageHandlers = {\n  chat: (data) => {\n    // \u804A\u5929\u6D88\u606F\u5904\u7406\n    return {\n      type: \'chat\',\n      id: data.id,\n      text: data.data.text,\n      sender: data.from,\n      timestamp: data.data.timestamp,\n    };\n  },\n  notification: (data) => {\n    // \u901A\u77E5\u6D88\u606F\u5904\u7406\n    return {\n      type: \'notification\',\n      title: data.data.title,\n      content: data.data.content,\n    };\n  },\n  system: (data) => {\n    // \u7CFB\u7EDF\u6D88\u606F\u5904\u7406\n    return {\n      type: \'system\',\n      action: data.data.action,\n    };\n  },\n};\n\n// \u5728onmessage\u4E2D\u4F7F\u7528\nwsClient.on(\'message\', (rawData) => {\n  const handler = messageHandlers[rawData.type];\n  if (handler) {\n    const message = handler(rawData);\n    // \u5206\u53D1\u5230\u5BF9\u5E94\u7684\u6D88\u606F\u961F\u5217\u6216\u72B6\u6001\u7BA1\u7406\n    // store.dispatch(addMessage(message));\n  } else {\n    console.warn(\'\u672A\u77E5\u6D88\u606F\u7C7B\u578B:\', rawData.type);\n  }\n});\n'})}),"\n",(0,r.jsxs)(n.p,{children:["\u8FD9\u79CD\u57FA\u4E8E\u6D88\u606F\u7C7B\u578B\u7684\u5206\u53D1\u6A21\u5F0F\uFF0C\u6700\u5927\u7684\u597D\u5904\u662F\u6269\u5C55\u6027\u6781\u5F3A\u2014\u2014\u65B0\u589E\u4E00\u79CD\u6D88\u606F\u7C7B\u578B\u53EA\u9700\u8981\u5728",(0,r.jsx)(n.code,{children:"messageHandlers"}),"\u5BF9\u8C61\u4E2D\u6DFB\u52A0\u4E00\u4E2A\u5BF9\u5E94\u7684\u5904\u7406\u51FD\u6570\uFF0C\u4E0D\u9700\u8981\u4FEE\u6539\u6D88\u606F\u63A5\u6536\u548C\u5206\u53D1\u7684\u6838\u5FC3\u903B\u8F91\u3002\u8FD9\u7B26\u5408\u5F00\u95ED\u539F\u5219\uFF1A\u5BF9\u6269\u5C55\u5F00\u653E\uFF0C\u5BF9\u4FEE\u6539\u5173\u95ED\u3002\u5728\u5B9E\u9645\u7684\u5373\u65F6\u901A\u8BAF\u9879\u76EE\u4E2D\uFF0C\u6D88\u6